with WebEventsBySession as (select session_id, max(duration_sec) - min(duration_sec) as duration_sec_range, avg(duration_sec) as avg_duration_sec from web_events where page <> '/cart' group by session_id) select s.id, s.device, W.duration_sec_range, W.avg_duration_sec from sessions s inner join WebEventsBySession W on s.id = W.session_id where W.duration_sec_range >= 55 order by id
